import sys


def read_three(stream):
    parts = []
    in_three = False

    for line in stream:
        if line.startswith(b">"):
            if in_three:
                break
            in_three = line.startswith(b">THREE")
        elif in_three and not line.startswith(b";"):
            part = line.strip()
            if part:
                parts.append(part)

    return b"".join(parts)


def main():
    n = int(sys.argv[1])
    sequence = read_three(sys.stdin.buffer).upper()
    length = len(sequence)

    # The benchmark uses ACGT; also handle other observed DNA symbols.
    extra = sequence.translate(None, b"ACGT")
    alphabet = sorted(set(b"ACGT").union(extra))
    del extra

    singles = {}
    for symbol in alphabet:
        fragment = bytes((symbol,))
        count = sequence.count(fragment)
        if count:
            singles[fragment] = count

    # Distinct-symbol pairs cannot overlap themselves, so bytes.count is exact.
    # Repeated-symbol counts follow from each symbol's total outgoing pairs.
    pairs = {}
    last = sequence[-1:] if sequence else b""
    for first, total in singles.items():
        repeated = total - (first == last)
        for second in singles:
            if first == second:
                continue
            fragment = first + second
            count = sequence.count(fragment)
            repeated -= count
            if count:
                pairs[fragment] = count
        if repeated:
            pairs[first + first] = repeated

    output = []
    for counts, denominator in ((singles, length), (pairs, length - 1)):
        for fragment, count in sorted(
            counts.items(), key=lambda item: (-item[1], item[0])
        ):
            output.append(
                f"{fragment.decode('ascii')} {100.0 * count / denominator:.3f}"
            )
        output.append("")

    # None of these fragments has a proper prefix equal to a suffix;
    # consequently, their occurrences cannot overlap.
    for fragment in (
        b"GGT",
        b"GGTA",
        b"GGTATT",
        b"GGTATTTTAATT",
        b"GGTATTTTAATTTATAGT",
    ):
        output.append(
            f"{sequence.count(fragment)}\t{fragment.decode('ascii')}"
        )

    sys.stdout.write("\n".join(output) + "\n")


if __name__ == "__main__":
    main()

